CREATE TABLE "AllTypes" (
  "RowID" INTEGER,
  "AByte" TINYINT,
  "AnInteger" SMALLINT,
  "ALong" INTEGER,
  "ASingle" FLOAT,
  "ADouble" DOUBLE,
  "ACurrency" TEXT,
  "ADate" DATETIME,
  "ABoolean" BOOLEAN NOT NULL DEFAULT 0,
  "AText" VARCHAR(255),
  "AMemo" TEXT,
  "AnOleObject" BLOB
);
CREATE TABLE "Customers" (
  "CustomerID" INTEGER PRIMARY KEY NOT NULL,
  "CompanyName" VARCHAR(60),
  "City" VARCHAR(40),
  "Credit" DECIMAL(19,4),
  "Since" DATETIME,
  "Active" BOOLEAN NOT NULL DEFAULT 0,
  "Notes" TEXT
);
CREATE TABLE "Orders" (
  "OrderID" INTEGER,
  "CustomerID" INTEGER,
  "Placed" DATETIME,
  "Total" DECIMAL(19,4),
  "Shipped" BOOLEAN NOT NULL DEFAULT 0,
  FOREIGN KEY ("CustomerID") REFERENCES "Customers" ("CustomerID") -- Access relationship: CustomersOrders
);
CREATE INDEX "Orders_CustomersOrders" ON "Orders" ("CustomerID");
